<script lang="ts">import type { MasonryColumns,MasonryLayoutDetail } from '@fex-design/svelte/primitive/masonry';import { MasonryItem,MasonryRoot,MasonryViewport } from '@fex-design/svelte/primitive/masonry';import { masonryItems } from './data';const configs:{title:string;columns:MasonryColumns}[]=[{title:'最小列宽',columns:{minColumnWidth:180,max:5}},{title:'容器断点',columns:[{minWidth:0,columns:1},{minWidth:480,columns:2},{minWidth:700,columns:3},{minWidth:900,columns:4}]}];let widths=$state([720,720]),counts=$state([0,0]);function layout(index:number,value:MasonryLayoutDetail){counts[index]=value.columnCount}</script>
<div class="grid gap-space-xl">{#each configs as config,configIndex(config.title)}<section class="grid gap-space-sm"><div><h3 class="font-medium">{config.title}</h3><p class="text-sm text-muted-foreground">容器 {widths[configIndex]}px · 当前 {counts[configIndex]||'…'} 列</p></div><input bind:value={widths[configIndex]} aria-label={`${config.title}容器宽度`} type="range" min="280" max="960"/><div class="max-w-full overflow-hidden" style:width={`${widths[configIndex]}px`}><MasonryRoot columns={config.columns} gap={12} onLayoutChange={value=>layout(configIndex,value)}><MasonryViewport>{#each masonryItems.slice(0,6) as item,index(item.id)}<MasonryItem itemKey={item.id} {index}><div class="rounded-md border border-border bg-muted-background p-space-sm" style:height={`${item.height/3}px`}>Card {index+1}</div></MasonryItem>{/each}</MasonryViewport></MasonryRoot></div></section>{/each}</div>
